{
  "probability": 0.71,
  "range_low": 0.60,
  "range_high": 0.82,
  "summary": [
    "Posterior probability is 0.71 (71%) that the IOM Missing Migrants Project records at least 900 Mediterranean migrant deaths in 2026 before April 2026, anchored on early-2026 pace and reference-class context.",
    "February 2026 tallies (~606 deaths by Feb 24) imply a substantial March toll would be required (roughly 294 more deaths) to hit 900, making the target plausible but not guaranteed.",
    "Weather risks and sustained high crossing activity could push totals higher, while data uncertainty and historical patterns counsel caution against overconfidence.",
    "Calibration yields a range of plausible outcomes (0.60–0.82) reflecting heterogeneity in pace, weather, and reporting revisions."
  ],
  "confidence": "medium",
  "narrative": "The analysis anchors on early-2026 death pace and the IOM reference class, updating for March-season risk factors and data uncertainty. The posterior of 71% arises from a balance of a high initial pace and the need for a sizable March toll, tempered by historical patterns and reporting variability.",
  "justification": {
    "anchor": {
      "probability": 0.60,
      "basis": "reference class anchored on IOM Missing Migrants Project counts for the Central Mediterranean and the February 2026 pace (~606 deaths by Feb 24), with historical annual tolls (~2,000–2,500) providing context for the magnitude of annual fatalities."
    },
    "factor_updates": [
      {
        "factor": "YTD Mediterranean death pace through February 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "606 deaths by Feb 24 suggest a high pace; to reach 900 by end-March requires roughly 294 more deaths, elevating the probability but still uncertain."
      },
      {
        "factor": "Severe weather events in January 2026 (e.g., cyclones)",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Storm activity increases peril of crossings and could sustain elevated tolls into March, nudging the total upward."
      },
      {
        "factor": "January 2026 described as deadliest month/start of year on record",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Record-start dynamics signal elevated risk, contributing positively to hitting 900 but with substantial uncertainty."
      },
      {
        "factor": "Historical first-quarter pattern implying a March surge would be required",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Past quarters show that hitting 900 by end-March would require an unusually large March, tempering the probability."
      },
      {
        "factor": "Data reporting gaps and potential revisions to counts",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Ongoing revisions and measurement uncertainty temper confidence in the precise tally and timing of reaching 900."
      }
    ],
    "synthesis_rationale": "Weights reflect a calibrated posterior that integrates a strong early-2026 pace with weather risk and reporting uncertainty, while acknowledging historical patterns that cap abrupt surges. Correlations among pace, weather, and data revisions are considered; the result is a mid-to-high calibrated probability with a moderate uncertainty band."
  }
}

{
  "probability": 0.71,
  "range_low": 0.60,
  "range_high": 0.80,
  "summary": [
    "Early 2026 IOM counts show about 606 Mediterranean deaths by late February, implying a high pace that would require roughly 294 more deaths in March to reach 900.",
    "Weather risks and sustained crossings could push March toll higher, but this is offset by uncertainties in reporting and potential SAR capacity changes.",
    "Historical seasonality suggests 900 by end-March would be unusual, making the event possible but not probable without a March surge.",
    "The calibrated posterior, after incorporating these updates and acknowledged data uncertainty, centers around 71%."
  ],
  "confidence": "medium",
  "narrative": "Starting from a high baseline anchored by February 2026 mortality pace, all considered updates tilt modestly around this path. The combined updates yield a posterior around 71%, with substantial uncertainty due to data revisions and weather/operational factors.",
  "justification": {
    "anchor": {
      "probability": 0.72,
      "basis": "IOM Missing Migrants Project-based counts for early 2026 (first two months) provide a reasonable anchor; this is consistent with multiple major outlets citing the same pace."
    },
    "factor_updates": [
      {
        "factor": "Year-to-date mortality pace in early 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Reported ~606 deaths by late Feb 2026 implies a high baseline pace; if continued, raises the chance of reaching 900 by end-March."
      },
      {
        "factor": "March toll required to reach 900 by end-March",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "To reach 900, need ~294 more deaths in March (~9–10 per day); a March surge would be comparatively unlikely given February pace."
      },
      {
        "factor": "Historical first-quarter pattern",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Past Q1 totals (e.g., 441 in Jan–Mar 2023) suggest a March surge would be exceptional, tempering the odds."
      },
      {
        "factor": "Severe weather events in early 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Storm-related fatalities and higher risk can elevate March tolls, contributing to a higher probability of reaching 900."
      },
      {
        "factor": "Policy and SAR capacity changes",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Improvements in rescue capacity or safer routes could limit fatalities, reducing the likelihood of hitting 900 by March."
      },
      {
        "factor": "Data reporting gaps and revisions",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Ongoing revisions to counts can shift the pace; this introduces uncertainty but not a directional bias."
      }
    ],
    "synthesis_rationale": "The posterior 0.71 emerges from updating the starting anchor with (a) strong signal of elevated pace, (b) a notably unlikely March surge requirement, (c) weather-driven risk uplift, (d) potential SAR capacity dampening, and (e) data uncertainty. Correlated factors and limited calibration data mean the final interval should be treated with cautious probability; the rounded posterior of 71% reflects these inputs, with a cautious 60–80% calibrated range."
  }
}

